with base as (select *, ceil(rating) as rating_whole from suppliers where city is not null) select *, rank() over (partition by city, country order by rating_whole nulls last) as rating_whole_rank, lag(rating_whole, 1, 0) over (partition by country order by rating, id) as prev_rating_whole, avg(rating) over (partition by country order by rating, id rows between 2 preceding and current row) as rating_avg_2, dense_rank() over (partition by country order by rating_whole nulls first) as rating_whole_dense_rank, last_value(rating, true) over (order by rating, id rows between unbounded preceding and current row) as last_known_rating from base;
